import sys,collections,heapq,itertools,functools,bisect
def solve(data):
    n,D=map(int,data.split())
    def f(mask,last):
        if mask==(1<<n)-1:return 1
        return sum(f(mask|1<<x,x) for x in range(n) if not(mask>>x&1) and (last<0 or abs(x-last)>=D))
    return f(0,-1)

if __name__=="__main__":
    a=solve(sys.stdin.buffer.read().decode())
    print(" ".join(map(str,a)) if isinstance(a,(list,tuple)) else a)
